'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type PointerEvent } from 'react';
import { useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { separation: number; pitch: number; pointer: number; perspective: number };

const LAYERS = [
  { name: 'Canvas', note: 'Page background and layout grid' },
  { name: 'Content', note: 'Cards, charts and lists' },
  { name: 'Navigation', note: 'Top bar and section rail' },
  { name: 'Overlay', note: 'Toast, focus ring and pointer' },
] as const;

export default function LayeredDepthStack({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const [separation, setSeparation] = useState(params.separation);
  const [yaw, setYaw] = useState(-34);
  const stack = useRef<HTMLDivElement>(null);
  const raf = useRef(0);
  const sepId = useId();
  const yawId = useId();

  useEffect(() => setSeparation(params.separation), [params.separation]);
  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  const tilt = (x: number, y: number) => {
    cancelAnimationFrame(raf.current);
    raf.current = requestAnimationFrame(() => {
      stack.current?.style.setProperty('--px', x.toFixed(3));
      stack.current?.style.setProperty('--py', y.toFixed(3));
    });
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (reduced || params.pointer === 0 || e.pointerType === 'touch') return;
    const r = e.currentTarget.getBoundingClientRect();
    if (r.width < 1 || r.height < 1) return;
    tilt(((e.clientX - r.left) / r.width) * 2 - 1, ((e.clientY - r.top) / r.height) * 2 - 1);
  };

  return (
    <div className={styles.root} data-reduced={reduced || undefined}>
      <div
        className={styles.scene}
        role="img"
        aria-label={`Exploded view of an interface in four layers, from bottom to top: ${LAYERS.map((l) => l.name).join(', ')}.`}
        style={{ perspective: `${params.perspective}px` }}
        onPointerMove={onPointerMove}
        onPointerLeave={() => tilt(0, 0)}
      >
        <div
          ref={stack}
          className={styles.stack}
          style={{ '--sep': `${separation}px`, '--k': separation / 110, '--pitch': `${params.pitch}deg`, '--yaw': `${yaw}deg`, '--reach': `${params.pointer}deg` } as CSSProperties}
        >
          <div className={`${styles.layer} ${styles.canvas}`} style={{ '--i': 0 } as CSSProperties}>
            <Tag n={1} name={LAYERS[0].name} />
          </div>
          <div className={`${styles.layer} ${styles.content}`} style={{ '--i': 1 } as CSSProperties}>
            <span className={styles.hero}><i /><i /><i /><i /><i /><i /><i /></span>
            <span className={styles.tile} />
            <span className={styles.tile} data-accent="" />
            <span className={styles.rows}><i /><i /><i /></span>
            <Tag n={2} name={LAYERS[1].name} />
          </div>
          <div className={`${styles.layer} ${styles.nav}`} style={{ '--i': 2 } as CSSProperties}>
            <span className={styles.bar}><b /><i /><i /><i /><em /></span>
            <span className={styles.rail}><i data-on="" /><i /><i /><i /></span>
            <Tag n={3} name={LAYERS[2].name} />
          </div>
          <div className={`${styles.layer} ${styles.overlay}`} style={{ '--i': 3 } as CSSProperties}>
            <span className={styles.ring} />
            <span className={styles.toast}><b /><i /><i /></span>
            <svg className={styles.cursor} viewBox="0 0 20 20" aria-hidden="true"><path d="M4 2.5v13l3.6-3.2 2.3 5.2 2.2-1-2.3-5.1 4.7-.3z" /></svg>
            <Tag n={4} name={LAYERS[3].name} />
          </div>
        </div>
      </div>

      <div className={styles.panel}>
        <ol className={styles.legend} reversed>
          {[...LAYERS].reverse().map((l, i) => (
            <li key={l.name}>
              <span className={styles.num} aria-hidden="true">{String(LAYERS.length - i).padStart(2, '0')}</span>
              <span><strong>{l.name}</strong><span className={styles.noteText}>{l.note}</span></span>
            </li>
          ))}
        </ol>
        <div className={styles.field}>
          <label htmlFor={sepId}>Separation <output htmlFor={sepId}>{separation} px</output></label>
          <input id={sepId} type="range" min={0} max={110} step={2} value={separation} onChange={(e) => setSeparation(Number(e.target.value))} />
        </div>
        <div className={styles.field}>
          <label htmlFor={yawId}>View angle <output htmlFor={yawId}>{yaw}°</output></label>
          <input id={yawId} type="range" min={-70} max={70} step={2} value={yaw} onChange={(e) => setYaw(Number(e.target.value))} />
        </div>
      </div>
    </div>
  );
}

function Tag({ n, name }: { n: number; name: string }) {
  return <span className={styles.tag} aria-hidden="true"><b>{String(n).padStart(2, '0')}</b>{name}</span>;
}

.root {
  --lw: clamp(190px, 46cqi, 330px);
  --lh: calc(var(--lw) * 0.68);
  --paper: #f3f0e8;
  --inkc: #11110f;
  display: grid;
  gap: 8px 32px;
  align-items: center;
  width: 100%;
  padding: 20px clamp(16px, 4cqi, 36px) 24px;
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}
@container (min-width: 680px) {
  .root { grid-template-columns: minmax(0, 1.5fr) minmax(220px, 1fr); }
}
.scene {
  display: grid;
  place-items: center;
  min-height: calc(var(--lh) * 1.25 + 210px);
  overflow: visible;
}
.stack {
  --px: 0;
  --py: 0;
  position: relative;
  width: var(--lw);
  height: var(--lh);
  transform-style: preserve-3d;
  /* translateZ centres the explosion so the stack grows both ways from the middle */
  transform:
    rotateX(calc(var(--pitch) - var(--py) * var(--reach) * 0.5))
    rotateZ(calc(var(--yaw) + var(--px) * var(--reach)))
    translateZ(calc(var(--sep) * -1.5));
  transition: transform var(--s3-duration-moderate, 360ms) var(--s3-ease-emphasized, cubic-bezier(0.16, 1, 0.3, 1));
}
.layer {
  position: absolute;
  inset: 0;
  border-radius: 10px;
  transform: translateZ(calc(var(--sep) * var(--i)));
  transition: transform var(--s3-duration-moderate, 360ms) var(--s3-ease-emphasized, cubic-bezier(0.16, 1, 0.3, 1));
}
.layer > * { position: absolute; }
/* Each drawn piece drops a shadow that lengthens with separation. */
.content > span:not(.tag), .nav > span:not(.tag), .toast {
  box-shadow: calc(var(--sep) * -0.16) calc(var(--sep) * 0.16) calc(var(--sep) * 0.3 + 1px) rgb(11 11 9 / calc(0.05 + var(--k) * 0.16));
}

/* 01 canvas */
.canvas {
  background:
    linear-gradient(#11110f14 1px, transparent 1px) 0 0 / 100% 12.5%,
    linear-gradient(90deg, #11110f14 1px, transparent 1px) 0 0 / 8.333% 100%,
    var(--paper);
  border: 1px solid #11110f40;
  box-shadow: calc(var(--sep) * -0.1 - 6px) calc(var(--sep) * 0.1 + 8px) 28px rgb(11 11 9 / 0.2);
}

/* 02 content */
.content > span:not(.tag) { border-radius: 6px; background: #fffdf8; border: 1px solid #11110f33; }
.hero { left: 21%; top: 21%; width: 45%; height: 40%; display: flex; align-items: flex-end; gap: 5%; padding: 7% 6% 6%; }
.hero i { flex: 1; border-radius: 2px 2px 0 0; background: #11110f; }
.hero i:nth-child(1) { height: 34%; } .hero i:nth-child(2) { height: 52%; } .hero i:nth-child(3) { height: 44%; }
.hero i:nth-child(4) { height: 70%; } .hero i:nth-child(5) { height: 58%; } .hero i:nth-child(6) { height: 88%; background: #e03a0c; }
.hero i:nth-child(7) { height: 64%; }
.tile { left: 69%; top: 21%; width: 26%; height: 18.5%; }
.tile[data-accent] { top: 42.5%; background: #0f6b57 !important; border-color: #0f6b57 !important; }
.rows { left: 21%; top: 65%; width: 74%; height: 29%; display: grid; align-content: space-evenly; padding: 0 5%; }
.rows i { height: 3px; border-radius: 2px; background: #11110f40; }
.rows i:nth-child(2) { width: 72%; } .rows i:nth-child(3) { width: 46%; }

/* 03 navigation */
.bar { left: 0; top: 0; width: 100%; height: 15%; border-radius: 10px 10px 0 0; background: var(--inkc); display: flex; align-items: center; gap: 4%; padding: 0 4%; }
.bar b { width: 5%; aspect-ratio: 1; border-radius: 50%; background: #e03a0c; }
.bar i { width: 9%; height: 3px; border-radius: 2px; background: #f3f0e899; }
.bar em { margin-left: auto; width: 14%; height: 44%; border-radius: 99px; border: 1px solid #f3f0e899; }
.rail { left: 0; top: 15%; width: 16%; height: 85%; border-radius: 0 0 0 10px; background: #26261f; display: grid; align-content: start; justify-items: center; gap: 9%; padding-top: 22%; }
.rail i { width: 38%; aspect-ratio: 1; border-radius: 3px; border: 1.5px solid #f3f0e880; }
.rail i[data-on] { background: #f3f0e8; border-color: #f3f0e8; }

/* 04 overlay */
.ring { left: 67.5%; top: 40%; width: 29%; height: 23.5%; border-radius: 8px; border: 2px solid #e03a0c; }
.toast { right: 5%; bottom: 7%; width: 44%; height: 21%; border-radius: 7px; background: #e03a0c; display: grid; grid-template-columns: auto 1fr; align-content: center; gap: 12% 8%; padding: 0 8%; }
.toast b { grid-row: span 2; align-self: center; width: 12px; aspect-ratio: 1; border-radius: 50%; border: 2px solid #fffaf2; }
.toast i { height: 3px; border-radius: 2px; background: #fffaf2; }
.toast i:last-child { width: 60%; opacity: 0.7; }
.cursor { left: 80%; top: 52%; width: 9%; fill: var(--inkc); stroke: #fffdf8; stroke-width: 1.2; filter: drop-shadow(-2px 3px 2px rgb(11 11 9 / 0.3)); }

.tag {
  left: calc(100% + 14px);
  bottom: 6px;
  display: flex;
  gap: 8px;
  align-items: baseline;
  white-space: nowrap;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--s3-ink, #11110f);
  opacity: calc(0.25 + var(--k) * 1.6);
  box-shadow: none;
  background: none;
  border: 0;
}
.tag::before { content: ''; position: absolute; right: calc(100% + 4px); bottom: 0.4em; width: 8px; height: 1px; background: currentColor; }
.tag b { font-weight: 500; color: var(--s3-accent, #e03a0c); }

.panel { display: grid; gap: 18px; min-width: 0; }
.legend { display: grid; margin: 0; padding: 0; list-style: none; }
.legend li { display: grid; grid-template-columns: 2.25rem 1fr; padding: 9px 0; border-top: 1px solid var(--s3-line, #11110f24); font-size: 0.875rem; line-height: 1.3; }
.legend li:last-child { border-bottom: 1px solid var(--s3-line, #11110f24); }
.legend strong { display: block; font-weight: 600; }
.num { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; color: var(--s3-accent, #e03a0c); padding-top: 3px; }
.noteText { color: var(--s3-ink-muted, #5c5a52); font-size: 0.8125rem; }
.field { display: grid; gap: 4px; }
.field label { display: flex; justify-content: space-between; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; }
.field output { color: var(--s3-ink-muted, #5c5a52); font-variant-numeric: tabular-nums; }
.field input { width: 100%; height: 28px; margin: 0; accent-color: var(--s3-ink, #11110f); cursor: pointer; }
.field input:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; border-radius: 4px; }

.root[data-reduced] .stack, .root[data-reduced] .layer { transition: none; }
@media (prefers-reduced-motion: reduce) {
  .stack, .layer { transition: none; }
}
/* On narrow stages the in-scene tags would clip; the text legend carries the names. */
@container (max-width: 520px) {
  .tag { display: none; }
}
